import re
from collections import Counter

def naive_tokenize(text):
    text = text.lower()
    return re.findall(r"[a-záéíóúñü]+", text)

reviews = [
    "Buen producto, aunque la caja llegó un poco dañada.",
    "¡Buen servicio! El envío fue rápido y sin daños.",
]

all_tokens = []
for review in reviews:
    all_tokens.extend(naive_tokenize(review))

freq = Counter(all_tokens)
for word, count in sorted(freq.items(), key=lambda kv: (-kv[1], kv[0]))[:5]:
    print(f"{word}: {count}")
